package com.skyclone.mod.mayors;

import com.google.gson.Gson;

import java.io.Reader;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;

/**
 * Every mayor and every perk, as data ({@code data/mayors/mayors.json}, generated by
 * {@code tools/gen/mayors/gen_mayors.py}). Pure Java: no Bukkit, so unit tests load the real file.
 *
 * <p>Perk ids are {@code <mayor>.<perk>} ("cole.mining_fiesta"). Each perk also lists aliases
 * ("cole.fiesta") so a module that guessed a slightly different id still reads the right perk.
 */
public final class MayorRoster {

    public static final class Perk {
        public String id;
        public String ref;
        public String name;
        public double value;
        /** Module that applies the effect; "mayors" = this module does. */
        public String owner;
        public List<String> lore = new ArrayList<>();
        public List<String> aliases = new ArrayList<>();
        public boolean ministerEligible = true;
    }

    public static final class Mayor {
        public String id;
        public String ref;
        public String name;
        public String type;
        public String color = "f";
        public String icon = "PLAYER_HEAD";
        public boolean special;
        public boolean retired;
        public List<Perk> perks = new ArrayList<>();

        /** "&amp;cVexmar" */
        public String display() { return "&" + color + name; }

        public List<String> perkIds() {
            List<String> out = new ArrayList<>();
            for (Perk p : perks) out.add(p.id);
            return out;
        }
    }

    public List<Mayor> mayors = new ArrayList<>();
    public List<String> specialRotation = new ArrayList<>();
    public List<String> perkpocalypseExclude = new ArrayList<>();

    private transient Map<String, Mayor> byId;
    private transient Map<String, Perk> perkById;
    private transient Map<String, String> alias;
    private transient Map<String, Mayor> mayorOfPerk;

    public static MayorRoster parse(Reader in) {
        MayorRoster r = new Gson().fromJson(in, MayorRoster.class);
        if (r == null) r = new MayorRoster();
        r.index();
        return r;
    }

    void index() {
        byId = new LinkedHashMap<>();
        perkById = new LinkedHashMap<>();
        alias = new HashMap<>();
        mayorOfPerk = new HashMap<>();
        for (Mayor m : mayors) {
            byId.put(m.id, m);
            for (Perk p : m.perks) {
                perkById.put(p.id, p);
                mayorOfPerk.put(p.id, m);
                alias.put(p.id, p.id);
                for (String a : p.aliases) alias.putIfAbsent(norm(a), p.id);
            }
        }
    }

    private static String norm(String s) { return s == null ? "" : s.trim().toLowerCase(Locale.ROOT); }

    public Mayor mayor(String id) { return id == null ? null : byId.get(norm(id)); }

    /** The canonical perk id for an id or alias, or null when unknown. */
    public String canonical(String idOrAlias) {
        if (idOrAlias == null) return null;
        return alias.get(norm(idOrAlias));
    }

    public Perk perk(String idOrAlias) {
        String c = canonical(idOrAlias);
        return c == null ? null : perkById.get(c);
    }

    public Mayor mayorOfPerk(String idOrAlias) {
        String c = canonical(idOrAlias);
        return c == null ? null : mayorOfPerk.get(c);
    }

    public Map<String, Perk> perks() { return Collections.unmodifiableMap(perkById); }

    /** Regular (non-special) mayors; retired ones only when asked. */
    public List<Mayor> regulars(boolean includeRetired) {
        List<Mayor> out = new ArrayList<>();
        for (Mayor m : mayors) if (!m.special && (includeRetired || !m.retired)) out.add(m);
        return out;
    }
}
